59: // A recorded outcome that the planner never reads changes nothing: run 9 proposed the very node
60: // whose outcome said it had just been worked, because it never opened the graph. Instructions do
61: // not reliably produce a tool call, so the durable state is supplied rather than offered.
62: async function priorGraph(path) {
63:   let text;
64:   try {
65:     text = await readFile(path, 'utf8');
66:   } catch (error) {
67:     if (error.code === 'ENOENT') return null;
68:     throw new Error(`Could not read the durable graph at ${path}: ${error.message}`);
69:   }
70:   const graph = JSON.parse(text);
71:   validateGraph(graph, graph?.objective);
72:   // Only the outcomes. Handed whole nodes, two runs returned them: same ids, same reasons, same
73:   // evidence strings, copied line numbers, and one file read between them. The node bodies are
74:   // answer-shaped and get copied; the outcomes are the part that exists nowhere else.
75:   return (graph.outcomes ?? []).map(item =>
76:     `- ${item.title} (recorded ${item.at}): ${item.outcome}`);
77: }
